  "staff.access.suspendedBody": "ผู้ดูแลระบบได้ระงับบัญชีพนักงานนี้สำหรับธุรกิจที่ใช้งานอยู่ ขอให้พวกเขาตั้งคุณกลับเป็นใช้งานอยู่ แล้วลงชื่อเข้าใช้อีกครั้ง",
  "staff.access.suspendedTitle": "สิทธิ์การเข้าถึงของคุณถูกหยุดชั่วคราว",
  "staff.addFirst": "เพิ่มสมาชิกพนักงานคนแรก",
  "staff.addMember": "เพิ่มสมาชิกพนักงาน",
  "staff.emptyBody": "เพิ่มบุคคล ให้บทบาทและสิทธิ์ที่มากับบทบาทแก่พวกเขา แล้วพวกเขาจะได้รับคำเชิญทางอีเมลให้ลงชื่อเข้าใช้ธุรกิจนี้",
  "staff.emptyTitle": "ยังไม่มีพนักงาน",
  "staff.eyebrow": "ทีม",
  "staff.how.p1": "สมาชิกทุกคนมีบทบาทและรายการสิทธิ์ของตัวเอง คุณจึงเริ่มจากบทบาทและเปลี่ยนสิ่งหนึ่งได้โดยไม่ต้องสร้างบทบาทใหม่ การแก้ไขบทบาทไม่เขียนทับสมาชิกที่อยู่บนบทบาทนั้นแล้ว — เปิดสมาชิกเพื่อใช้ค่าเริ่มต้นของบทบาทอีกครั้ง",
  "staff.how.p2": "บทบาทกำหนดเองเป็นฟีเจอร์ของแผน Business: Essentials ใช้บทบาทในตัวห้าบทบาท (เจ้าของ, ผู้จัดการ, พนักงานคลังสินค้า, พนักงานขาย, ผู้ชม)",
  "staff.how.p3": "คำเชิญจะถูกส่งทางอีเมล สมาชิกจะลงชื่อเข้าใช้ได้ก็ต่อเมื่อยอมรับคำเชิญแล้ว และการนำใครออกจากรายการนี้ไม่ได้ลบบัญชีแอปของพวกเขา",
  "staff.how.p4": "ร้านคือสถานที่ที่บุคคลถูกมอบหมายให้ประจำ ถูกบันทึกไว้บนบัตรของพวกเขา สิ่งที่พวกเขาเปิดได้ยังคงตัดสินโดยบทบาทและสิทธิ์ของพวกเขา",
  "staff.how.p5": "สิทธิ์ตัดสินว่าแต่ละคนเปิดอะไรได้: รายการเมนูที่อยู่นอกบทบาทของพวกเขาจะถูกซ่อน และที่อยู่ที่ถูกบล็อกจะแสดงประกาศ “ไม่อยู่ในบทบาทของคุณ” แทนหน้าเพจ การเปลี่ยนแปลงมีผลในครั้งถัดไปที่บุคคลนั้นโหลดแอป การระงับสมาชิกจะล็อกพวกเขาไม่ให้เข้าใช้ทั้งหมด",
  "staff.how.p6": "ผู้ดูแลระบบสามารถเห็นและเปลี่ยนแปลงข้อมูลทั้งหมด จัดการผู้ใช้แอปและบทบาท และไม่เคยถูกจำกัดโดยบทบาทพนักงาน ผู้ที่ไม่มีบันทึกพนักงาน — เจ้าของธุรกิจใหม่ — ยังคงเข้าถึงได้เต็มรูปแบบ",
