  "settings.security.changeEmailTitle": "Change your account email",
  "settings.security.changeEmailDesc": "Move your account to a new email. Your shop, inventory, team and history move with it — and no new free trial starts. Every other signed-in device is signed out.",
  "settings.security.newEmailLabel": "New email",
  "settings.security.currentPasswordLabel": "Current password",
